'use client';

import { useState } from 'react';
import {
  LiveKitRoom,
  RoomAudioRenderer,
  StartAudio,
  useVoiceAssistant,
  BarVisualizer,
  VoiceAssistantControlBar,
  useChat,
  useRoomContext,
  useConnectionState,
} from '@livekit/components-react';
import '@livekit/components-styles';
import { MessageSquare, Mic, Volume2 } from 'lucide-react';
import { ConnectionState } from 'livekit-client';

interface VoiceAppWithChatProps {
  token: string;
  serverUrl: string;
  onDisconnect?: () => void;
  agentName?: string;
}

export function VoiceAppWithChat({ token, serverUrl, onDisconnect, agentName }: VoiceAppWithChatProps) {
  return (
    <LiveKitRoom
      token={token}
      serverUrl={serverUrl}
      connect={true}
      audio={true}
      video={false}
      onDisconnected={onDisconnect}
      className="h-full w-full"
    >
      <VoiceAndChatLayout agentName={agentName} />
      <div className="fixed top-4 left-1/2 transform -translate-x-1/2 z-50">
        <StartAudio 
          label="🔊 Click to Enable Audio" 
          className="bg-green-500 hover:bg-green-600 text-white font-bold px-6 py-3 rounded-lg shadow-lg animate-pulse"
        />
      </div>
      <RoomAudioRenderer />
    </LiveKitRoom>
  );
}

function VoiceAndChatLayout({ agentName }: { agentName?: string }) {
  const { state, audioTrack } = useVoiceAssistant();
  const { chatMessages, send: sendMessage } = useChat();
  const room = useRoomContext();
  const connectionState = useConnectionState();
  const [message, setMessage] = useState('');

  const handleSendMessage = () => {
    if (message.trim()) {
      sendMessage(message);
      setMessage('');
    }
  };

  const getConnectionStateText = () => {
    switch (connectionState) {
      case ConnectionState.Connecting:
        return '🔌 Connecting...';
      case ConnectionState.Connected:
        return '✅ Connected';
      case ConnectionState.Reconnecting:
        return '🔄 Reconnecting...';
      case ConnectionState.Disconnected:
        return '❌ Disconnected';
      default:
        return '⏳ Initializing...';
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 h-full p-4">
      {/* Voice Panel */}
      <div className="flex flex-col bg-gradient-to-br from-blue-50 to-purple-50 dark:from-gray-900 dark:to-gray-800 rounded-2xl border-2 border-blue-200 dark:border-gray-700 p-6 shadow-xl">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-xl font-bold flex items-center gap-2">
            <Volume2 className="w-6 h-6 text-blue-600" />
            Voice Agent
          </h3>
          <div className="text-sm font-semibold px-3 py-1 rounded-full bg-white dark:bg-gray-800 shadow">
            {getConnectionStateText()}
          </div>
        </div>

        {/* Audio Enable Reminder */}
        {!audioTrack && connectionState === ConnectionState.Connected && (
          <div className="bg-yellow-100 dark:bg-yellow-900 border-2 border-yellow-500 rounded-lg p-4 mb-4">
            <p className="text-yellow-800 dark:text-yellow-200 font-semibold mb-2">
              🔊 Can't Hear the AI?
            </p>
            <p className="text-sm text-yellow-700 dark:text-yellow-300">
              Click the green "Enable Audio" button at the top!
            </p>
          </div>
        )}

        {/* Agent Status */}
        <div className="flex-1 flex flex-col items-center justify-center space-y-6">
          <div className="text-center space-y-2">
            <h4 className="text-2xl font-bold">
              {state === 'connecting' && '🔌 Connecting to agent...'}
              {state === 'initializing' && '⚙️ Initializing...'}
              {state === 'listening' && '👂 Listening...'}
              {state === 'thinking' && '🤔 Thinking...'}
              {state === 'speaking' && '🗣️ Speaking...'}
              {state === 'disconnected' && '❌ Disconnected'}
              {!state && '⏳ Waiting for agent...'}
            </h4>
            {agentName && (
              <p className="text-sm text-muted-foreground">
                Agent: {agentName}
              </p>
            )}
            <p className="text-xs text-muted-foreground">
              Room: {room.name}
            </p>
          </div>

          {/* Visualizer */}
          {audioTrack && (
            <div className="w-full max-w-md">
              <BarVisualizer
                state={state}
                barCount={7}
                trackRef={audioTrack}
                className="h-32"
                options={{ minHeight: 30 }}
              />
            </div>
          )}

          <VoiceAssistantControlBar />
        </div>

        {/* Instructions */}
        <div className="mt-auto pt-4 border-t border-gray-200 dark:border-gray-700">
          <p className="text-sm font-semibold mb-2">💡 Quick Tips:</p>
          <ul className="text-xs space-y-1 text-muted-foreground">
            <li>• Allow microphone access when prompted</li>
            <li>• Speak clearly: "I'd like to book an appointment"</li>
            <li>• AI will respond with voice and text</li>
          </ul>
        </div>
      </div>

      {/* Chat/Transcript Panel */}
      <div className="flex flex-col bg-gradient-to-br from-green-50 to-teal-50 dark:from-gray-900 dark:to-gray-800 rounded-2xl border-2 border-green-200 dark:border-gray-700 shadow-xl overflow-hidden">
        <div className="flex items-center justify-between p-4 border-b border-green-200 dark:border-gray-700 bg-white/50 dark:bg-gray-800/50">
          <h3 className="text-xl font-bold flex items-center gap-2">
            <MessageSquare className="w-6 h-6 text-green-600" />
            Live Transcript
          </h3>
          <div className="text-xs text-muted-foreground">
            {chatMessages.length} messages
          </div>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {chatMessages.length === 0 ? (
            <div className="flex items-center justify-center h-full text-center">
              <div className="text-muted-foreground">
                <Mic className="w-12 h-12 mx-auto mb-2 opacity-50" />
                <p className="text-sm">Start speaking to see the conversation here</p>
                <p className="text-xs mt-1">Transcript will appear in real-time</p>
              </div>
            </div>
          ) : (
            chatMessages.map((msg, idx) => (
              <div
                key={idx}
                className={`flex ${
                  msg.from?.identity.includes('agent') || msg.from?.identity.includes('assistant')
                    ? 'justify-start'
                    : 'justify-end'
                }`}
              >
                <div
                  className={`max-w-[80%] rounded-2xl px-4 py-2 ${
                    msg.from?.identity.includes('agent') || msg.from?.identity.includes('assistant')
                      ? 'bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 border border-gray-200 dark:border-gray-700'
                      : 'bg-blue-600 text-white'
                  }`}
                >
                  <div className="text-xs opacity-70 mb-1">
                    {msg.from?.identity.includes('agent') || msg.from?.identity.includes('assistant') 
                      ? '🤖 AI Agent' 
                      : '👤 You'}
                  </div>
                  <p className="text-sm whitespace-pre-wrap">{msg.message}</p>
                  <div className="text-xs opacity-60 mt-1">
                    {new Date(msg.timestamp).toLocaleTimeString()}
                  </div>
                </div>
              </div>
            ))
          )}
        </div>

        {/* Input */}
        <div className="p-4 border-t border-green-200 dark:border-gray-700 bg-white/50 dark:bg-gray-800/50">
          <div className="flex gap-2">
            <input
              type="text"
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()}
              placeholder="Type a message (optional)..."
              className="flex-1 px-4 py-2 rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-green-500"
              disabled={connectionState !== ConnectionState.Connected}
            />
            <button
              onClick={handleSendMessage}
              disabled={!message.trim() || connectionState !== ConnectionState.Connected}
              className="px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 disabled:opacity-50 disabled:cursor-not-allowed font-medium transition-colors"
            >
              Send
            </button>
          </div>
          <p className="text-xs text-muted-foreground mt-2">
            💡 Voice is the main input - typing is optional for testing
          </p>
        </div>
      </div>
    </div>
  );
}
